package javaclassparser

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

// Both assertion fields are generated by javac. The child and its lexical
// status owner deliberately receive opposite loader overrides. The producer
// observes the child's field reentrantly before an optional initializer failure;
// querying the lexical owner's status must not initialize that owner.
const adversarialAssertionStatusOwnerFixture = `class StatusEffects {
 static String trace="";
 static final RuntimeException token=new IllegalStateException("initialization");
 static boolean failLeaf=FAIL_LEAF,failOwner=true;
 static int produce(Class<?> type){
  trace+="P";
  try{java.lang.reflect.Field f=type.getDeclaredField("$assertionsDisabled");f.setAccessible(true);
   if(!f.isSynthetic()||f.getModifiers()!=0x1018)throw new AssertionError("compiler flag metadata");
   trace+=f.getBoolean(null)?"d":"e";
  }catch(ReflectiveOperationException e){throw new AssertionError(e);}
  if(failLeaf)throw token;
  return 7;
 }
 static boolean condition(boolean value,String mark){trace+=mark;return value;}
 static String message(String text,String mark){trace+=mark;return text;}
}
class StatusSubjectBase {
 static int check(boolean value){assert StatusEffects.condition(value,"B"):StatusEffects.message("base","Q");return 3;}
}
class StatusSubjectScope {
 static{StatusEffects.trace+="O";if(StatusEffects.failOwner)throw StatusEffects.token;}
 static class Cell extends StatusSubjectBase {
  static final int value=StatusEffects.produce(StatusSubjectScope.Cell.class);
  int checkLeaf(boolean flag){assert StatusEffects.condition(flag,"C"):StatusEffects.message("leaf","M");return value;}
 } // cell end
} // scope end
class StatusDriver {
 public static void main(String[]args)throws Exception{
  ClassLoader loader=ClassLoader.getSystemClassLoader();
  loader.setClassAssertionStatus("StatusSubjectBase",!OWNER_ENABLED);
  loader.setClassAssertionStatus("StatusSubjectScope",OWNER_ENABLED);
  loader.setClassAssertionStatus("StatusSubjectScope$Cell",!OWNER_ENABLED);
  StatusEffects.trace="";
  String leaf="initialization-failure",base="not-run";
  if(FAIL_LEAF){
   try{new StatusSubjectScope.Cell();throw new AssertionError("missing initialization failure");}
   catch(ExceptionInInitializerError e){if(e.getCause()!=StatusEffects.token)throw new AssertionError("failure identity",e);}
   String once=StatusEffects.trace;
   try{new StatusSubjectScope.Cell();throw new AssertionError("missing erroneous class");}catch(NoClassDefFoundError expected){}
   if(!once.equals(StatusEffects.trace))throw new AssertionError("repeated initializer");
  }else{
   StatusSubjectScope.Cell cell=new StatusSubjectScope.Cell();
   try{leaf="value-"+cell.checkLeaf(false);}catch(AssertionError e){leaf=e.getMessage();}
   try{base="value-"+StatusSubjectBase.check(false);}catch(AssertionError e){base=e.getMessage();}
  }
  // A class literal used by the compiler protocol must not have run this
  // initializer while constructing the child or checking either assertion.
  if(StatusEffects.trace.indexOf("O")>=0)throw new AssertionError("premature lexical owner initialization");
  try{Class.forName("StatusSubjectScope",true,loader);throw new AssertionError("missing owner failure");}
  catch(ExceptionInInitializerError e){if(e.getCause()!=StatusEffects.token)throw new AssertionError("owner failure identity",e);}
  String once=StatusEffects.trace;
  try{Class.forName("StatusSubjectScope",true,loader);throw new AssertionError("missing erroneous owner");}catch(NoClassDefFoundError expected){}
  if(!once.equals(StatusEffects.trace))throw new AssertionError("repeated owner initializer");
  System.out.println("leaf="+leaf+";base="+base+";trace="+StatusEffects.trace+";owner="+OWNER_ENABLED);
 }
}`

func adversarialAssertionStatusFixture(renamed, enabled, fail bool) (string, string) {
	f := strings.NewReplacer("OWNER_ENABLED", fmt.Sprint(enabled), "FAIL_LEAF", fmt.Sprint(fail)).Replace(adversarialAssertionStatusOwnerFixture)
	owner := "StatusSubject"
	if renamed {
		f = strings.NewReplacer("StatusSubject", "RenamedDomain", "Cell", "Leaf", "checkLeaf", "inspectLeaf").Replace(f)
		owner = "RenamedDomain"
	}
	return f, owner
}

func adversarialAssertionWrite(t *testing.T, root, name string, raw []byte) {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(name))
	if err := os.MkdirAll(filepath.Dir(p), 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, raw, 0600); err != nil {
		t.Fatal(err)
	}
}

func adversarialAssertionClasses(t *testing.T, files map[string][]byte) string {
	t.Helper()
	dir := t.TempDir()
	for n, raw := range files {
		adversarialAssertionWrite(t, dir, n, raw)
	}
	return dir
}

// Optional evidence is outside the checkout; the assertions below remain the
// same in CI. It preserves the exact authored and rebuilt inputs for a separate
// classfile oracle rather than inferring metadata from generated source.
func adversarialAssertionEvidence(t *testing.T, context, name string, raw []byte) {
	t.Helper()
	if root := os.Getenv("JDEC_ASSERTION_OWNER_EVIDENCE"); root != "" {
		adversarialAssertionWrite(t, filepath.Join(root, t.Name(), context), name, raw)
	}
}

func TestAdversarialAssertionStatusOwnerLexicalFamily(t *testing.T) {
	javac, java := t04Tools(t)
	for _, renamed := range []bool{false, true} {
		for _, mode := range []struct{ enabled, fail bool }{{false, false}, {true, false}, {true, true}} {
			t.Run(fmt.Sprintf("renamed=%t/enabled=%t/fail=%t", renamed, mode.enabled, mode.fail), func(t *testing.T) {
				fixture, owner := adversarialAssertionStatusFixture(renamed, mode.enabled, mode.fail)
				files := nativeCompileClasses(t, fixture)
				original := adversarialAssertionClasses(t, files)
				oracle := t04RunJava(t, java, original, "StatusDriver")
				want := "leaf=value-7;base=base;trace=PdBQO;owner=false\n"
				if mode.enabled {
					want = "leaf=leaf;base=value-3;trace=PeCMO;owner=true\n"
				}
				if mode.fail {
					want = "leaf=initialization-failure;base=not-run;trace=PeO;owner=true\n"
				}
				if oracle != want {
					t.Fatalf("original JVM=%q want=%q", oracle, want)
				}
				jar := filepath.Join(t.TempDir(), "authored.jar")
				if err := os.WriteFile(jar, t23Zip(t, files), 0600); err != nil {
					t.Fatal(err)
				}
				z, err := NewJarFSFromLocalWithCompilerProfile(jar, 8, ModernJavac, nil)
				if err != nil {
					t.Fatal(err)
				}
				defer z.Close()
				out := t.TempDir()
				var paths []string
				adversarialAssertionEvidence(t, "", "authored.java", []byte(fixture))
				for n, raw := range files {
					adversarialAssertionEvidence(t, "original", n, raw)
					if !strings.HasPrefix(n, owner) {
						adversarialAssertionWrite(t, out, n, raw)
						continue
					}
					source, err := z.ReadFile(n)
					if err != nil || strings.Contains(string(source), DecompileStubMarker) {
						t.Fatalf("source %s: %v\n%s", n, err, source)
					}
					name := strings.TrimSuffix(n, ".class") + ".java"
					adversarialAssertionWrite(t, out, name, source)
					adversarialAssertionEvidence(t, "source", name, source)
					paths = append(paths, filepath.Join(out, name))
				}
				if raw, err := exec.Command(javac, append([]string{"-proc:none", "--release", "8", "-g:none", "-cp", out, "-d", out}, paths...)...).CombinedOutput(); err != nil {
					t.Fatalf("rebuilt: %v\n%s", err, raw)
				}
				if got := t04RunJava(t, java, out, "StatusDriver"); got != oracle {
					t.Fatalf("rebuilt JVM=%q want=%q", got, oracle)
				}
				for n, raw := range files {
					if !strings.HasPrefix(n, owner) {
						continue
					}
					got, err := os.ReadFile(filepath.Join(out, n))
					if err != nil {
						t.Fatal(err)
					}
					adversarialAssertionEvidence(t, "rebuilt", n, got)
					if a, b := nativeBinaryShape(t, raw), nativeBinaryShape(t, got); a != b {
						t.Fatalf("ABI %s\n%s\n%s", n, a, b)
					}
					nativeLexicalExactSignatures(t, n, raw, got)
					a, err := Parse(raw)
					if err != nil {
						t.Fatal(err)
					}
					b, err := Parse(got)
					if err != nil {
						t.Fatal(err)
					}
					if !slices.Equal(nativeNestedEnumMetadataShape(t, a), nativeNestedEnumMetadataShape(t, b)) {
						t.Fatalf("complete InnerClasses changed: %s", n)
					}
				}
				t.Logf("ModernJavac/target8 original and rebuilt: %s", strings.TrimSpace(oracle))
			})
		}
	}
}

func TestAdversarialAssertionStatusOwnerCannotBeFlattened(t *testing.T) {
	_, java := t04Tools(t)
	for _, renamed := range []bool{false, true} {
		for _, enabled := range []bool{false, true} {
			t.Run(fmt.Sprintf("renamed=%t/enabled=%t", renamed, enabled), func(t *testing.T) {
				fixture, owner := adversarialAssertionStatusFixture(renamed, enabled, false)
				cell := "Cell"
				if renamed {
					cell = "Leaf"
				}
				// A separately compiled source alternative is intentionally not
				// a qualification result: it loses the original lexical metadata.
				// No flags or generated assertion fields are edited in either input.
				flat := strings.Replace(fixture, " static class "+cell+" extends", "}\nclass "+owner+"Scope$"+cell+" extends", 1)
				flat = strings.Replace(flat, "\n} // scope end", "", 1)
				flat = strings.ReplaceAll(flat, owner+"Scope."+cell, owner+"Scope$"+cell)
				var outputs []string
				for i, source := range []string{fixture, flat} {
					context := []string{"lexical", "flat"}[i]
					files := nativeCompileClasses(t, source)
					for n, raw := range files {
						adversarialAssertionEvidence(t, context, n, raw)
					}
					adversarialAssertionEvidence(t, context, "authored.java", []byte(source))
					outputs = append(outputs, t04RunJava(t, java, adversarialAssertionClasses(t, files), "StatusDriver"))
				}
				if outputs[0] == outputs[1] {
					t.Fatalf("flattened assertion borrowed lexical status: %q", outputs)
				}
				t.Logf("lexical=%s flat=%s", strings.TrimSpace(outputs[0]), strings.TrimSpace(outputs[1]))
			})
		}
	}
}
